import openpyxl
from openpyxl.worksheet.formula import ArrayFormula
p1='/mnt/hhq/data/answer_files/3_55135_answer.xlsx'
p2='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_55135_answer_template_3997_golden.xlsx'
w1=openpyxl.load_workbook(p1, data_only=False)
w2=openpyxl.load_workbook(p2, data_only=False)
def norm(v):
    if isinstance(v, ArrayFormula): return ('ARR', v.text)
    return v
diff=0
for sh in w1.sheetnames:
    s1=w1[sh]; s2=w2[sh]
    for row in s1.iter_rows():
        for c in row:
            v1=norm(c.value); v2=norm(s2[c.coordinate].value)
            if v1!=v2:
                diff+=1
                if diff<20:
                    print('DIFF',sh,c.coordinate,repr(v1),repr(v2))
print('total diffs', diff)
